#!/bin/bash
# level-build-json.sh - fresh-VM-safe data-driven level iteration job (v9)
# Generated by bus-jobs/build_level_job.py - DO NOT hand-edit the C# heredocs;
# edit game/mfps/*.cs and regenerate instead.
set -e

