using System;
using System.IO;
using Newtonsoft.Json;
using UnityEngine;

// Data classes deserialized from the level layout JSON (specs/heist-bank-v1.json).
// Positions are float[] because JSON arrays cannot map onto UnityEngine.Vector3.
// Newtonsoft.Json is used because it is referenced by the Unity project
// (com.unity.nuget.newtonsoft-json) and compiles green in this pipeline.
public class LevelLayoutData
{
    [JsonProperty("name")]
    public string levelName;
    [JsonProperty("version")]
    public int version;
    [JsonProperty("description")]
    public string description;
    [JsonProperty("rooms")]
    public LevelRoomData[] rooms;
    [JsonProperty("globalSpawnPoints")]
    public LevelSpawnPointData[] globalSpawnPoints;
}

[System.Serializable]
public class LevelRoomData
{
    [JsonProperty("id")]
    public string roomId;
    [JsonProperty("props")]
    public LevelPropData[] props;
    [JsonProperty("spawnPoints")]
    public LevelSpawnPointData[] spawnPoints;
    [JsonProperty("killZones")]
    public LevelKillZoneData[] killZones;
}

[System.Serializable]
public class LevelPropData
{
    [JsonProperty("prefab")]
    public string prefabPath;
    [JsonProperty("position")]
    public float[] position;
    [JsonProperty("rotation")]
    public float[] rotation;
    [JsonProperty("scale")]
    public float[] scale;
    [JsonProperty("tag")]
    public string tag;
}

[System.Serializable]
public class LevelSpawnPointData
{
    [JsonProperty("position")]
    public float[] position;
    [JsonProperty("team")]
    public int team;
    [JsonProperty("type")]
    public string type;
}

[System.Serializable]
public class LevelKillZoneData
{
    [JsonProperty("position")]
    public float[] position;
    [JsonProperty("size")]
    public float[] size;
}

// ScriptableObject mirror of the layout data; saved as an asset that the
// scene builder reads. Lives in Assets/Editor (editor-only pipeline).
public class LevelLayout : ScriptableObject
{
    public string levelName;
    public int version;
    public string description;
    public LevelRoomData[] rooms;
    public LevelSpawnPointData[] globalSpawnPoints;
    public string layoutJsonPath;
}

#if UNITY_EDITOR
public static class LevelLayoutGenerator
{
    public static void Generate()
    {
        string jsonPath = "/content/level-layout.json";
        if (!File.Exists(jsonPath))
        {
            Debug.LogError("LEVEL_LAYOUT: no layout file at " + jsonPath);
            throw new Exception("LEVEL_LAYOUT: no layout file at " + jsonPath);
        }

        string json = File.ReadAllText(jsonPath);
        LevelLayoutData data = JsonConvert.DeserializeObject<LevelLayoutData>(json);
        if (data == null || data.rooms == null || data.rooms.Length == 0)
        {
            throw new Exception("LEVEL_LAYOUT: failed to deserialize layout JSON");
        }

        LevelLayout asset = ScriptableObject.CreateInstance<LevelLayout>();
        asset.levelName = string.IsNullOrEmpty(data.levelName) ? "Unnamed" : data.levelName;
        asset.version = data.version;
        asset.description = data.description;
        asset.rooms = data.rooms;
        asset.globalSpawnPoints = data.globalSpawnPoints;
        asset.layoutJsonPath = jsonPath;

        System.IO.Directory.CreateDirectory("Assets/Resources");
        string assetPath = "Assets/Resources/LevelLayout.asset";
        UnityEditor.AssetDatabase.CreateAsset(asset, assetPath);
        UnityEditor.AssetDatabase.SaveAssets();
        LevelLayout verify = Resources.Load<LevelLayout>("LevelLayout");
        if (verify == null || verify.rooms == null || verify.rooms.Length == 0)
        {
            throw new Exception("LEVEL_LAYOUT: asset did not serialize rooms (verify=" +
                (verify == null ? "LOAD_FAIL" : "rooms_null") + ")");
        }
        Debug.Log("LEVEL_LAYOUT: generated " + assetPath + " name=" + asset.levelName +
            " rooms=" + asset.rooms.Length + " VERIFY_ROOMS=" + verify.rooms.Length);
    }
}
#endif
CSEOF1
cat > "$PROJ/Assets/Editor/LevelBuilder.cs" <<'CSEOF2'
using System;
using System.IO;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;

// Builds the level scene from a LevelLayout asset and wires the full MFPS
// gameplay layer (GameManager, AIManager, ItemManager, UI, spawn points,
// KillZone) using the recipe proven in heist-t1-5.
public static class LevelBuilder
{
    static int spawnCounter;

    public static void BuildFromLayoutAsset()
    {
        LevelLayout layout = Resources.Load<LevelLayout>("LevelLayout");
        if (layout == null || layout.rooms == null)
        {
            throw new Exception("LEVEL_BUILDER: LevelLayout asset unusable (loaded=" + (layout != null) +
                " rooms_null=" + (layout != null && layout.rooms == null) + "). Run LevelLayoutGenerator.Generate first.");
        }

        Debug.Log("LEVEL_BUILDER: building '" + layout.levelName + "' v" + layout.version + " rooms=" + layout.rooms.Length);

        var scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);

        // Floor so nothing falls through the grey plane
        GameObject floor = GameObject.CreatePrimitive(PrimitiveType.Plane);
        floor.name = "Floor";
        floor.transform.position = new Vector3(0f, 0f, 0f);
        floor.transform.localScale = new Vector3(20f, 1f, 20f);

        GameObject levelRoot = new GameObject("LevelRoot_" + layout.levelName.Replace(" ", "_"));
        spawnCounter = 0;

        foreach (LevelRoomData room in layout.rooms)
        {
            if (room == null || string.IsNullOrEmpty(room.roomId)) continue;
            GameObject roomRoot = new GameObject("Room_" + room.roomId);
            roomRoot.transform.SetParent(levelRoot.transform, false);

            if (room.props != null)
            {
                foreach (LevelPropData prop in room.props)
                {
                    if (prop == null || string.IsNullOrEmpty(prop.prefabPath)) continue;
                    GameObject prefab = AssetDatabase.LoadAssetAtPath<GameObject>(prop.prefabPath);
                    if (prefab == null)
                    {
                        Debug.LogWarning("LEVEL_BUILDER: prefab not found: " + prop.prefabPath);
                        continue;
                    }
                    GameObject inst = (GameObject)PrefabUtility.InstantiatePrefab(prefab, scene);
                    inst.transform.position = ToV3(prop.position, Vector3.zero);
                    inst.transform.eulerAngles = ToV3(prop.rotation, Vector3.zero);
                    inst.transform.localScale = ToV3(prop.scale, Vector3.one);
                    inst.transform.SetParent(roomRoot.transform, true);
                }
            }

            if (room.spawnPoints != null)
            {
                foreach (LevelSpawnPointData sp in room.spawnPoints)
                {
                    CreateSpawnPoint(sp, scene);
                }
            }
        }

        if (layout.globalSpawnPoints != null)
        {
            foreach (LevelSpawnPointData sp in layout.globalSpawnPoints)
            {
                CreateSpawnPoint(sp, scene);
            }
        }

        // MFPS wiring (heist-t1-5 recipe)
        InstantiateMfpsPrefab(scene, "Assets/MFPS/Content/Prefabs/Network/GameManager.prefab", "GameManager");
        InstantiateMfpsPrefab(scene, "Assets/MFPS/Content/Prefabs/GamePlay/AIManager.prefab", "AIManager");
        InstantiateMfpsPrefab(scene, "Assets/MFPS/Content/Prefabs/GamePlay/ItemManager.prefab", "ItemManager");
        InstantiateMfpsPrefab(scene, "Assets/MFPS/Content/Prefabs/UI/UI.prefab", "UI");

        GameObject gameModes = new GameObject("GameModes");
        gameModes.transform.position = Vector3.zero;

        // Mark level geometry static and bake a NavMesh so AI agents can navigate
        floor.isStatic = true;
        levelRoot.isStatic = true;
        MarkStaticRecursive(levelRoot.transform);
        try
        {
            UnityEditor.AI.NavMeshBuilder.BuildNavMesh();
            Debug.Log("LEVEL_BUILDER: NavMesh baked");
        }
        catch (System.Exception e)
        {
            Debug.LogWarning("LEVEL_BUILDER: NavMesh bake failed (non-fatal): " + e.Message);
        }

        // Assign Photon scene-view IDs (PUN needs 1..999 for scene objects; ID 0 breaks
        // RPC delivery -> countdown never finishes -> player never spawns)
        Photon.Pun.PhotonView[] pvs = Object.FindObjectsByType<Photon.Pun.PhotonView>(FindObjectsSortMode.None);
        int sid = 1;
        foreach (Photon.Pun.PhotonView pv in pvs)
        {
            if (pv == null) continue;
            if (pv.Owner == null && pv.ViewID == 0)
            {
                pv.ViewID = sid;
                sid++;
            }
        }
        Debug.Log("LEVEL_BUILDER: photon scene views assigned=" + (sid - 1));

        string kzPath = "Assets/MFPS/Content/Prefabs/GamePlay/Level/KillZone.prefab";
        GameObject kzPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(kzPath);
        if (kzPrefab != null)
        {
            GameObject kz = (GameObject)PrefabUtility.InstantiatePrefab(kzPrefab, scene);
            kz.transform.position = new Vector3(0f, -5f, 0f);
            kz.transform.localScale = new Vector3(200f, 1f, 200f);
            Debug.Log("LEVEL_BUILDER: KillZone placed");
        }
        else
        {
            Debug.LogWarning("LEVEL_BUILDER: KillZone prefab not found: " + kzPath);
        }

        // Save + register the scene for the player build
        string savePath = "Assets/MFPS/Scenes/HeistLevel.unity";
        Directory.CreateDirectory("Assets/MFPS/Scenes");
        EditorSceneManager.SaveScene(scene, savePath);

        var buildScenes = new System.Collections.Generic.List<EditorBuildSettingsScene>();
        string mainMenuPath = "Assets/MFPS/Scenes/MainMenu.unity";
        if (File.Exists(mainMenuPath))
        {
            buildScenes.Add(new EditorBuildSettingsScene(mainMenuPath, true));
            Debug.Log("LEVEL_BUILDER: MainMenu added to build list (safety)");
        }
        buildScenes.Add(new EditorBuildSettingsScene(savePath, true));
        EditorBuildSettings.scenes = buildScenes.ToArray();

        Debug.Log("LEVEL_BUILDER: scene saved " + savePath + " spawns=" + spawnCounter + " BUILD_SCENES_SET");
    }

    static void CreateSpawnPoint(LevelSpawnPointData sp, Scene scene)
    {
        if (sp == null) return;
        string name = "DeltaSpawn_" + spawnCounter;
        spawnCounter++;
        GameObject obj = new GameObject(name);
        SceneManager.MoveGameObjectToScene(obj, scene);
        obj.transform.position = ToV3(sp.position, new Vector3(0f, 1f, 0f));
        bl_SpawnPoint bsp = obj.AddComponent<bl_SpawnPoint>();
        int team = sp.team <= 0 ? 1 : sp.team;
        bsp.m_Team = (global::Team)team;
        Debug.Log("LEVEL_BUILDER: spawn " + name + " team=" + team + " type=" + sp.type);
    }

    static void InstantiateMfpsPrefab(Scene scene, string path, string goName)
    {
        GameObject prefab = AssetDatabase.LoadAssetAtPath<GameObject>(path);
        if (prefab == null)
        {
            throw new Exception("LEVEL_BUILDER: missing MFPS prefab " + path);
        }
        GameObject inst = (GameObject)PrefabUtility.InstantiatePrefab(prefab, scene);
        inst.transform.position = Vector3.zero;
        inst.name = goName;
        Debug.Log("LEVEL_BUILDER: wired " + goName);
    }

    static Vector3 ToV3(float[] a, Vector3 def)
    {
        if (a != null && a.Length >= 3) return new Vector3(a[0], a[1], a[2]);
        return def;
    }

    static void MarkStaticRecursive(Transform t)
    {
        foreach (Transform child in t)
        {
            child.gameObject.isStatic = true;
            MarkStaticRecursive(child);
        }
    }
}
CSEOF2
cat > "$PROJ/Assets/Editor/PerfTune.cs" <<'CSEOF3'
using System.Collections;
using UnityEngine;
using UnityEngine.SceneManagement;

// PerfTune: forces a low-end-friendly profile at runtime so MFPS is playable
// on integrated GPUs (Intel HD 620) and 2-core laptops. Applies before the
// scene loads, then kills post-processing layers once objects exist.
public static class PerfTune
{
    static bool s_applied;

    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
    static void Apply()
    {
        if (s_applied) return;
        s_applied = true;

        Debug.Log("PERF_BEFORE quality=" + QualitySettings.GetQualityLevel()
            + "/" + (QualitySettings.names.Length - 1)
            + " shadows=" + QualitySettings.shadows
            + " shadowDist=" + QualitySettings.shadowDistance
            + " pixelLights=" + QualitySettings.pixelLightCount
            + " aa=" + QualitySettings.antiAliasing
            + " vSync=" + QualitySettings.vSyncCount
            + " screen=" + Screen.width + "x" + Screen.height
            + " fullscreen=" + Screen.fullScreen);

        int low = 0;
        QualitySettings.SetQualityLevel(low, true);

        QualitySettings.shadows = ShadowQuality.HardOnly;
        QualitySettings.shadowDistance = 22f;
        QualitySettings.shadowCascades = 1;
        QualitySettings.shadowResolution = ShadowResolution.Low;
        QualitySettings.pixelLightCount = 1;
        QualitySettings.antiAliasing = 0;
        QualitySettings.anisotropicFiltering = AnisotropicFiltering.Disable;
        QualitySettings.softParticles = false;
        QualitySettings.softVegetation = false;
        QualitySettings.realtimeReflectionProbes = false;
        QualitySettings.billboardsFaceCameraPosition = false;
        QualitySettings.lodBias = 0.7f;
        QualitySettings.globalTextureMipmapLimit = 1;
        QualitySettings.vSyncCount = 1;
        Application.targetFrameRate = 30;

        Debug.Log("PERF_AFTER quality=" + QualitySettings.GetQualityLevel()
            + " shadows=" + QualitySettings.shadows
            + " shadowDist=" + QualitySettings.shadowDistance
            + " pixelLights=" + QualitySettings.pixelLightCount
            + " aa=" + QualitySettings.antiAliasing
            + " texLimit=" + QualitySettings.globalTextureMipmapLimit
            + " targetFps=" + Application.targetFrameRate);
    }

    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
    static void AfterScene()
    {
        Screen.SetResolution(1280, 720, FullScreenMode.Windowed);

        int disabled = 0;
        MonoBehaviour[] all = Object.FindObjectsByType<MonoBehaviour>(FindObjectsSortMode.None);
        for (int i = 0; i < all.Length; i++)
        {
            MonoBehaviour mb = all[i];
            if (mb == null) continue;
            string tn = mb.GetType().Name;
            if (tn == "PostProcessLayer" || tn == "PostProcessVolume")
            {
                mb.enabled = false;
                disabled++;
            }
        }
        Debug.Log("PERF_POSTPROCESSING_DISABLED=" + disabled);

        GameObject go = new GameObject("PerfHud");
        Object.DontDestroyOnLoad(go);
        go.AddComponent<PerfHud>();
    }
}

// Lightweight on-screen FPS readout so playtest reports carry a number.
public class PerfHud : MonoBehaviour
{
    float acc;
    int frames;
    float fps;
    float logTimer;
    bool logged;

    void Update()
    {
        acc += Time.unscaledDeltaTime;
        frames++;
        if (acc >= 0.5f)
        {
            fps = frames / acc;
            acc = 0f;
            frames = 0;
        }

        logTimer += Time.unscaledDeltaTime;
        if (!logged && logTimer > 20f)
        {
            logged = true;
            Debug.Log("PERF_FPS_SAMPLE=" + Mathf.RoundToInt(fps));
        }
    }

    void OnGUI()
    {
        GUI.Label(new Rect(12f, 10f, 260f, 26f),
            "FPS " + Mathf.RoundToInt(fps) + "    " + Screen.width + "x" + Screen.height);
    }
}
CSEOF3
cat > "$PROJ/Assets/Editor/MfpsBuild.cs" <<'CSEOF4'
using System.IO;
using UnityEditor;
using UnityEditor.Build.Reporting;
using UnityEngine;

public static class MfpsBuild
{
    public static void BuildWindows()
    {
        string outDir = "Builds/Win";
        Directory.CreateDirectory(outDir);
        string exePath = Path.Combine(outDir, "MFPSPrototype.exe");

        BuildPlayerOptions opts = new BuildPlayerOptions();
        opts.scenes = new[] { "Assets/MFPS/Scenes/HeistLevel.unity" };
        opts.locationPathName = exePath;
        opts.target = BuildTarget.StandaloneWindows64;
        opts.options = BuildOptions.None;

        BuildReport report = BuildPipeline.BuildPlayer(opts);
        if (report.summary.result != BuildResult.Succeeded)
        {
            Debug.LogError("BUILD_FAILED: " + report.summary.result);
            foreach (var step in report.steps)
                foreach (var msg in step.messages)
                    if (msg.type == LogType.Error)
                        Debug.LogError("BUILD_MSG " + msg.content);
            throw new System.Exception("BUILD_FAILED: " + report.summary.result);
        }
        Debug.Log("BUILD_RESULT Succeeded errors=" + report.summary.totalErrors + " warnings=" + report.summary.totalWarnings + " size=" + report.summary.totalSize);
    }
}
CSEOF4

for f in LevelLayout.cs LevelBuilder.cs PerfTune.cs MfpsBuild.cs; do
  md5sum "$PROJ/Assets/Editor/$f"
  wc -l "$PROJ/Assets/Editor/$f"
done
echo "FINGERPRINTS_ABOVE_PROVE_FRESH"

echo "=== COMPILE ENV ==="
rm -rf "$PROJ/Temp"
mkdir -p /tmp/xdg; chmod 700 /tmp/xdg
export XDG_RUNTIME_DIR=/tmp/xdg
printf 'pcm.!default { type null }\nctl.!default { type null }\n' > /etc/asound.conf || true

echo "=== GENERATE LEVEL LAYOUT ASSET ==="
"$UNITY" -batchmode -nographics -quit -projectPath "$PROJ" -executeMethod LevelLayoutGenerator.Generate -logFile /content/levellayout_gen.log 2>&1 || true
if grep -q "Aborting batchmode" /content/levellayout_gen.log 2>/dev/null; then
  echo "GEN_FAIL"
  grep -n "error CS\|Exception\|Aborting batchmode" /content/levellayout_gen.log | head -25
  tail -10 /content/levellayout_gen.log
  exit 6
fi
if [ ! -f "$PROJ/Assets/Resources/LevelLayout.asset" ]; then
  echo "ASSET_MISSING"
  tail -20 /content/levellayout_gen.log
  exit 6
fi
echo "ASSET_OK"

echo "=== BUILD LEVEL SCENE + MFPS WIRING ==="
rm -f "$PROJ/Assets/MFPS/Scenes/HeistLevel.unity"
"$UNITY" -batchmode -nographics -quit -projectPath "$PROJ" -executeMethod LevelBuilder.BuildFromLayoutAsset -logFile /content/level_build.log 2>&1 || true
if grep -q "Aborting batchmode" /content/level_build.log 2>/dev/null; then
  echo "LEVEL_BUILD_FAIL"
  grep -n "error CS\|Exception\|Aborting batchmode" /content/level_build.log | head -25
  tail -10 /content/level_build.log
  exit 6
fi
if [ ! -f "$PROJ/Assets/MFPS/Scenes/HeistLevel.unity" ]; then
  echo "SCENE_MISSING"
  tail -20 /content/level_build.log
  exit 6
fi
grep -E "LEVEL_BUILDER: (scene saved|wired|spawn)" /content/level_build.log | head -20
echo "LEVEL_SCENE_OK"

echo "=== BUILD WINDOWS ==="
"$UNITY" -batchmode -nographics -quit -projectPath "$PROJ" -executeMethod MfpsBuild.BuildWindows -logFile /content/win_build.log 2>&1 || true
if grep -q "Aborting batchmode" /content/win_build.log 2>/dev/null; then
  echo "WIN_FAIL_ABORT"
  grep -n "error CS\|Exception\|Aborting batchmode" /content/win_build.log | head -25
  exit 6
fi
if ! grep -q "BUILD_RESULT Succeeded" /content/win_build.log 2>/dev/null; then
  echo "WIN_BUILD_FAIL"
  grep -n "BUILD_FAILED\|BUILD_MSG\|Exception" /content/win_build.log | head -20
  tail -10 /content/win_build.log
  exit 6
fi
grep -n "BUILD_RESULT" /content/win_build.log | tail -1

echo "=== STAGE ==="
STAMP=$(date +%s)
BUNDLE="$PROJ/Builds/Win"
if [ ! -f "$BUNDLE/MFPSPrototype.exe" ]; then echo "NO_EXE"; exit 6; fi
cd "$PROJ" && zip -qr "/tmp/mfps-level-$STAMP.zip" "Builds/Win" && echo "ZIPPED"
ls -lh "/tmp/mfps-level-$STAMP.zip"
mkdir -p "$MFPSROOT/builds"
cp "/tmp/mfps-level-$STAMP.zip" "$MFPSROOT/builds/mfps-level-$STAMP.zip" && echo "STAGED_OK"
echo "MFPS_LEVEL_ZIP=mfps-level-$STAMP.zip"
mkdir -p "$MFPSROOT/templates/mfps-2.0-v1.75"
cp "$PROJ/Assets/Editor/LevelLayout.cs" "$PROJ/Assets/Editor/LevelBuilder.cs" "$PROJ/Assets/Editor/PerfTune.cs" "$MFPSROOT/templates/mfps-2.0-v1.75/" 2>/dev/null && echo "SCRIPTS_CACHED_TO_DRIVE" || echo "SCRIPTS_CACHE_SKIPPED"
echo "LEVEL_BUILD_COMPLETE"
